            expect(canUseRecentRollRerollItemForRecentRoll(core, '0', 'lucky-coin'), kind).toBe(false);
            expect(resolveRecentRollRerollSelectableDieIndices(core.recentRoll!, 'lucky-coin'), kind).toEqual([]);
