        core = applyBetrayalCommand(core, BETRAYAL_COMMANDS.MOVE_TO_ROOM, '0', { roomId: 'basement-east' });
        core.currentExplorer.inventory = [
            ...core.currentExplorer.inventory,
            { id: 'dagger', name: '匕首', kind: 'omen' },
        ];
